import Vue from 'vue';
import { Component, Emit, Prop } from 'vue-property-decorator';
import { SvgIcon } from '@game-studio/svg-icons';

@Component({
    name: 'GamePopoutMessage',
    components: {
        SvgIcon
    }
})
export default class GamePopoutMessage extends Vue {
    @Prop({
        required: false,
        type: Boolean,
        default: true
    })
    public visible: boolean;

    @Prop({
        required: true,
        type: String
    })
    public title: string;

    @Prop({
        required: true,
        type: String
    })
    public message: string;

    @Prop({
        required: true,
        type: String
    })
    public buttonText: string;

    @Emit('onOpen')
    public onOpen() {
        this.onClose();
    }

    @Emit('onClose')
    public onClose() {
    }
}
